algorithm_contract.reference_pseudocode:
float sdRing(float2 p,float r,float w){return abs(length(p)-r)-w;}
float aaMask(float d){float a=max(fwidth(d),1e-4);return 1-smoothstep(-a,a,d);}
float pulse=0.65+0.35*sin(Time*PulseHz+Phase);
alpha*=aaMask(sdRing(local,Radius,EdgeWidth))*pulse;

float2 q=Rotate(LocalUv,Rotation);
float d=min(sdCapsule(q,a,b,w),sdTriangle(q,...));
float edge=1-smoothstep(0.0,fwidth(d)*1.5,d);
return Color*edge;

float n=fbm(p*Scale + flow*Time);
float warp=fbm(p*Scale2 + n*Warp + Time*Speed);
float mask=smoothstep(Threshold,Threshold+Softness,warp);
emissive=Gradient(mask)*HDR;

p.x += (fbm(p*3+float2(0,-Time*2))-0.5)*Warp;
float taper=lerp(1.0,0.15,saturate(p.y*0.5+0.5));
float body=1-smoothstep(taper*0.45,taper,abs(p.x));
float flame=body*smoothstep(.25,.7,fbm(p*4+float2(0,-Time*3)));

// Ribbon vertices are generated from history in VFX_RibbonBuildCS.
float u = ArcLength / max(TotalLength, 1e-4);
float width = SampleCurve(WidthCurve, NormalizedAge) * WidthScale;
float3 tangent = normalize(NextPos - PrevPos);
float3 side = normalize(cross(ViewDir, tangent));
float3 world = Center + side * SideSign * width;
float edge = saturate(1.0 - abs(SideCoord));
float flow = SampleFlowMask(float2(SideCoord*0.5+0.5, u*UvRepeat-Time*Scroll));
float3 emissive = SampleGradient(GradientIndex, u) * HDR * edge * flow;

float2 n = ProceduralNormal(LocalUv, Time);
float depthFade = SoftDepth(SceneDepth, VfxDepth, Softness);
float w = Alpha * depthFade;
OutVector += n * Strength * w;
OutWeight += w;
// Resolve: offset = clamp(AccumVector/max(Weight,1e-4), -MaxOffset, MaxOffset);

float3 world = GBufferPosition.Load(int3(pixel,0)).xyz;
float3 local = mul(float4(world,1), WorldToDecal).xyz;
clip(1.0 - max(max(abs(local.x),abs(local.y)),abs(local.z)));
float d = EvaluateDecalSdf(local.xz, ShapeId, Params);
float a = AaMask(d) * Opacity;
OutAlbedoEmissive = float4(Tint * AlbedoWeight + Emissive * EmissiveWeight, a);
OutNormalWeight = float4(EncodeNormal(BlendNormal(SceneNormal, DecalNormal, a)), a);

float ndl=saturate(dot(N,-LightDir));
float fres=pow(1-saturate(dot(N,V)),FresnelPower);
float3 rgb=Base*(0.3+0.7*ndl)+Emissive*HDR+FresnelColor*fres;

float transmittance = 1.0;
float3 radiance = 0;
for(uint i=0;i<Steps;i++){
    float3 p = ro + rd * t;
    float density = Density(p, Time) * BoundsMask(p);
    float sigmaT = density * Extinction;
    float stepT = exp(-sigmaT * StepSize);
    float3 Li = Ambient + KeyLight * PhaseHG(dot(rd,-LightDir), Anisotropy);
    radiance += transmittance * (1.0-stepT) * Li * Albedo;
    transmittance *= stepT;
    if(transmittance < 0.03 || t > sceneT) break;
    t += StepSize;
}
OutColor = float4(radiance, 1.0-transmittance);

float fres=pow(1-saturate(dot(N,V)),Power);
float noise=fbm(WorldPos*Scale+Time*Speed);
alpha=fres*lerp(1,noise,NoiseAmount)*Opacity;

float edge=pow(saturate(length(UV-.5)*2),EdgePower);
float dir=saturate(dot(normalize(UV-.5),HitDirScreen));
float mask=edge*lerp(1,dir,Directional);
Out=Color*mask*Pulse;

float4 clip=mul(float4(nextPos,1),ViewProjection);
float2 uv=clip.xy/clip.w*.5+float2(.5,-.5);
float3 scene=GBufferPosition.SampleLevel(PointClamp,uv,0).xyz;
if(dot(nextPos-scene,ViewDir)>0){velocity=reflect(velocity,SceneNormal)*Restitution;}

float4 tex = SampleMaskOrFlipbook(Uv, Frame, ResourceIndex);
float edge = SoftParticleDepthFade(WorldPos, SceneDepth, Softness);
float a = tex.a * Opacity * edge;
float3 e = PaletteGradient.SampleLevel(LinearClamp,float2(GradientT,0.5),0).rgb * HDRIntensity;
ReactiveMask = max(ReactiveMask, saturate(a * ReactiveScale));
return float4(e * a, a);

if (Importance >= LightImportanceThreshold && Luminance(Emissive) > MinLuma) {
  uint tileMin,tileMax; ComputeLightTileBounds(Position,Radius,tileMin,tileMax);
  AppendCappedVfxLight(Position, Radius, Color*Intensity, Importance, StableId);
}

uint i = DispatchThreadID.x;
HistoryPoint p0 = History[i-1], p1 = History[i], p2 = History[i+1];
float3 tangent = normalize(p2.pos-p0.pos);
float3 side = SafeRibbonSide(tangent, CameraForward, p1.facingMode);
float u = ArcLengthPrefix[i] / max(TotalArcLength,1e-4);
float w = SampleCurve(WidthCurve,u);
WriteRibbonVertices(i,p1.pos, p1.prevPos, side*w, u, JoinMode);

bool visible = FrustumAndScreenCull(Bounds);
uint bin = ProfileBin(RenderProfileId);
uint laneCount = WaveActiveCountBits(visible);
uint waveBase = WaveIsFirstLane()? AtomicAdd(BinCount[bin],laneCount):0;
waveBase = WaveReadLaneFirst(waveBase);
uint dst = waveBase + WavePrefixCountBits(visible);
if(visible) BinIndices[bin][dst]=ParticleIndex;

float2 curr = ClipToUv(CurrentClip);
float2 prev = ClipToUv(PreviousClip);
MotionVector = curr - prev;
ReactiveMask = max(ReactiveMask, MaterialReactive);

float2 prevUv = uv - MotionVector;
float3 history = History.SampleLevel(LinearClamp,prevUv,0).rgb;
float3 curr = CurrentHdr[px];
float reactive = ReactiveMask[px];
float reject = max(reactive, DepthNormalDisocclusion(...));
float3 clipped = ClipHistoryToNeighborhood(history,curr,px);
Out[px] = lerp(clipped,curr,saturate(BaseCurrentWeight + reject*ReactiveBoost));

float2 prevUv = uv - VolumeMotion;
float4 hist = VolumeHistory.SampleLevel(LinearClamp,prevUv,0);
float reject = VolumeDisocclusion(SceneDepth, PrevDepth, DensityDelta);
float4 temporal = lerp(hist, CurrentVolume, saturate(HistoryReject + reject));
FullResOut = BilateralUpsample(temporal, SceneDepth, SceneNormal);

float n = BlueNoise3D(WorldPos*NoiseScale + Time*Flow);
float edge = smoothstep(Cutoff-EdgeWidth,Cutoff,n)-smoothstep(Cutoff,Cutoff+EdgeWidth,n);
clip(n-Cutoff);
BaseColor += EdgeColor * edge * EdgeHDR;

float3 c = LoadHdr(px);
float l = max(max(c.r,c.g),c.b);
float soft = saturate((l-Threshold+Knee)/(2*Knee));
float contrib = max(l-Threshold,0.0) + soft*soft*Knee;
float3 pref = c * contrib / max(l,1e-4);
DownMip = FireflyResistantDownsample(pref);
Upsampled = LowMip + TentUpsample(HighMip) * Scatter;

float3 linear = max(SceneHdr + Bloom, 0.0);
float3 exposed = linear * exp2(ExposureEV);
float3 mapped = AcesOrApprovedToneCurve(exposed);
float3 graded = UseLut ? ColorGrade3DLUT(mapped) : mapped;
Out = LinearToOutputTransfer(graded);

slice=ClipBase+Frame; pos=SmokePos.Sample(slice); neg=SmokeNeg.Sample(slice);
Llocal=normalize(WorldToParticleBasis*(-LightDir));
wp=max(Llocal,0); wn=max(-Llocal,0);
lit=(dot(pos.rgb,wp)+dot(neg.rgb,wn))/max(abs(Llocal.x)+abs(Llocal.y)+abs(Llocal.z),1e-4);
alpha=pos.a; emissive=neg.a*GradientColor*HDR;
High quality optionally warps adjacent frames with SmokeMotionVectors before interpolation.
